// Village demo v1. One connected settlement, daily abstraction, no combat.
// Inputs are explicit capabilities, never guessed from names or decorative geometry.
export const VILLAGE_SCHEMA = 1;
const resources=['rawFood','fuel','clay','vessels','food'];
const caps=['housing','garden','woodland','pottery','preservation','gathering'];
const natural=(v,label,max=1000000)=>{if(!Number.isSafeInteger(v)||v<0||v>max)throw new Error(`Invalid ${label}`);return v;};
const clone=v=>JSON.parse(JSON.stringify(v));
export function validateVillageBoard(board){
 if(!board||typeof board.id!=='string'||!board.id||!Array.isArray(board.instances)||!Array.isArray(board.connections))throw new Error('Invalid village board');
 natural(board.revision,'board revision');natural(board.population,'population',10000);
 const ids=new Set();for(const i of board.instances){if(typeof i.instanceId!=='string'||!i.instanceId||ids.has(i.instanceId))throw new Error('Duplicate or missing instance ID');ids.add(i.instanceId);if(typeof i.cardId!=='string'||!i.cardId)throw new Error('Missing source card ID');natural(i.cardRevision,'card revision');for(const [k,v]of Object.entries(i.capabilities||{})){if(!caps.includes(k))throw new Error(`Unsupported capability ${k}`);natural(v,k,10000);}for(const [k,v]of Object.entries(i.initialStock||{})){if(!resources.includes(k))throw new Error(`Unsupported resource ${k}`);natural(v,k);}}
 for(const e of board.connections)if(!ids.has(e.a)||!ids.has(e.b)||e.a===e.b||typeof e.valid!=='boolean')throw new Error('Invalid access edge');
 return board;
}
function network(board){validateVillageBoard(board);const root=board.instances.filter(i=>i.capabilities?.housing>0).sort((a,b)=>a.instanceId.localeCompare(b.instanceId))[0];const connected=new Set(root?[root.instanceId]:[]);let changed=true;while(changed){changed=false;for(const e of board.connections){if(!e.valid)continue;if(connected.has(e.a)&&!connected.has(e.b)){connected.add(e.b);changed=true;}if(connected.has(e.b)&&!connected.has(e.a)){connected.add(e.a);changed=true;}}}const totals=Object.fromEntries(caps.map(k=>[k,0]));for(const i of board.instances)if(connected.has(i.instanceId))for(const k of caps)totals[k]+=i.capabilities?.[k]||0;return {root:root?.instanceId,connected,totals};}
export function createVillageState(board){validateVillageBoard(board);return {schemaVersion:VILLAGE_SCHEMA,boardId:board.id,boardRevision:board.revision,revision:0,day:0,stock:Object.fromEntries(resources.map(k=>[k,0])),stockGranted:[],claimedGoals:[],inspiration:0,crafted:{vessels:0,preservedFood:0},lastDay:null,events:[]};}
function checkState(s,b){validateVillageBoard(b);if(!s||s.schemaVersion!==VILLAGE_SCHEMA||s.boardId!==b.id)throw new Error('Village state does not belong to this board');for(const k of ['revision','day','inspiration'])natural(s[k],k);for(const k of resources)natural(s.stock?.[k],k);for(const k of ['vessels','preservedFood'])natural(s.crafted?.[k],k);if(!Array.isArray(s.stockGranted)||new Set(s.stockGranted).size!==s.stockGranted.length||!s.stockGranted.every(x=>typeof x==='string'))throw new Error('Invalid stock ledger');if(!Array.isArray(s.claimedGoals)||new Set(s.claimedGoals).size!==s.claimedGoals.length||!s.claimedGoals.every(x=>['housing','winter-reserve','shared-meal'].includes(x)))throw new Error('Invalid goal ledger');}
export function inspectVillage(state,board){checkState(state,board);const n=network(board),p=board.population;const warnings=[];if(!n.root)warnings.push({code:'no-household',instanceIds:[],message:'Place a home to establish the village.'});for(const i of board.instances)if(!n.connected.has(i.instanceId))warnings.push({code:'disconnected',instanceIds:[i.instanceId],message:'No verified access route to the household; resources and services are unavailable.'});if(n.totals.housing<p)warnings.push({code:'housing-shortfall',instanceIds:n.root?[n.root]:[],message:`Housing for ${n.totals.housing} of ${p} residents.`});
 const goal=(id,title,ready,progress,target)=>({id,title,ready:ready&&!state.claimedGoals.includes(id),claimed:state.claimedGoals.includes(id),progress,target,reward:{inspiration:1}});
 return {day:state.day,population:p,connectedInstanceIds:[...n.connected],capacities:n.totals,stock:{...state.stock},foodReserveDays:p?state.stock.food/p:0,warnings,goals:[goal('housing','A home for everyone',p>0&&n.totals.housing>=p,n.totals.housing,p),goal('winter-reserve','Three days of food',p>0&&state.stock.food>=p*3,state.stock.food,p*3),goal('shared-meal','Share a communal meal',p>0&&n.totals.gathering>=p&&state.stock.food>=p,Math.min(n.totals.gathering,p),p)],lastDay:state.lastDay,discovered:state.crafted.vessels>0?['pottery']:[],limitations:['One household-connected service network','Daily work allocation; transfer is abstracted, not simulated travel','Population is the available adult workforce for this demo','Initial clay is finite; no mining or full technology tree yet']};
}
export function advanceVillage(state,board,{days=1}={}){checkState(state,board);natural(days,'days',365);if(days<1)throw new Error('Advance at least one day');const next=clone(state),n=network(board);next.boardRevision=board.revision;next.events=[];
 for(let d=0;d<days;d++){next.day++;let workers=Math.min(board.population,n.totals.housing),jobs=[];const event=(kind,data)=>{const e={id:`${next.revision+1}:${next.day}:${next.events.length}`,day:next.day,kind,...data};next.events.push(e);};
 for(const i of board.instances){if(n.connected.has(i.instanceId)&&!next.stockGranted.includes(i.instanceId)){for(const k of resources)next.stock[k]+=i.initialStock?.[k]||0;next.stockGranted.push(i.instanceId);if(Object.keys(i.initialStock||{}).length)event('stock-delivered',{instanceId:i.instanceId,resources:{...i.initialStock}});}}
 const production=(cap,fn)=>{for(const i of board.instances.filter(i=>i.capabilities?.[cap]>0).sort((a,b)=>a.instanceId.localeCompare(b.instanceId))){if(!n.connected.has(i.instanceId)){jobs.push({instanceId:i.instanceId,job:cap,status:'blocked',reason:'No verified access route'});continue;}if(workers<1){jobs.push({instanceId:i.instanceId,job:cap,status:'blocked',reason:'No available housed worker'});continue;}const result=fn(i.capabilities[cap]);if(!result.amount){jobs.push({instanceId:i.instanceId,job:cap,status:'blocked',reason:result.reason});continue;}workers--;jobs.push({instanceId:i.instanceId,job:cap,status:'working',amount:result.amount,resource:result.resource});event('production',{instanceId:i.instanceId,job:cap,...result});}};
 production('garden',cap=>{next.stock.rawFood+=cap;return {amount:cap,resource:'rawFood',inputs:{}};});
 production('woodland',cap=>{next.stock.fuel+=cap;return {amount:cap,resource:'fuel',inputs:{}};});
 production('pottery',cap=>{const count=Math.min(cap,next.stock.clay,next.stock.fuel);next.stock.clay-=count;next.stock.fuel-=count;next.stock.vessels+=count;next.crafted.vessels+=count;return {amount:count,resource:'vessels',inputs:{clay:count,fuel:count},reason:'Needs clay and fuel'};});
 production('preservation',cap=>{const batches=Math.min(cap,Math.floor(next.stock.rawFood/8),next.stock.vessels);next.stock.rawFood-=batches*8;next.stock.vessels-=batches;next.stock.food+=batches*8;next.crafted.preservedFood+=batches*8;return {amount:batches*8,resource:'food',inputs:{rawFood:batches*8,vessels:batches},reason:'Needs eight raw food and one vessel per batch'};});
 const fed=Math.min(board.population,next.stock.food);next.stock.food-=fed;event('household-meal',{foodConsumed:fed,unfed:board.population-fed});next.lastDay={day:next.day,jobs,workersUsed:Math.min(board.population,n.totals.housing)-workers,foodConsumed:fed,unfed:board.population-fed};if(next.events.length>400)next.events=next.events.slice(-400);
 for(const k of resources)natural(next.stock[k],k);}
 next.revision++;return next;
}
export function claimVillageGoal(state,board,goalId){const report=inspectVillage(state,board),goal=report.goals.find(x=>x.id===goalId);if(!goal)throw new Error('Unknown village goal');if(goal.claimed)return clone(state);if(!goal.ready)throw new Error('Goal requirements are not satisfied');const next=clone(state);if(goalId==='shared-meal')next.stock.food-=board.population;next.claimedGoals.push(goalId);next.inspiration++;next.revision++;next.boardRevision=board.revision;next.events=[{id:`goal:${goalId}`,kind:'goal-claimed',goalId,day:next.day,reward:{inspiration:1},foodConsumed:goalId==='shared-meal'?board.population:0}];return next;}
